import sys
input = sys.stdin.read().split()
n = int(input[0])
operations = input[1::2]
constants = list(map(int, input[2::2]))

and_result = 1023
or_result = 0
xor_result = 0

for op, const in zip(operations, constants):
    if op == '&':
        and_result &= const
    elif op == '|':
        or_result |= const
    elif op == '^':
        xor_result ^= const

result = []
if and_result < 1023:
    result.append(('&', and_result))
if or_result > 0:
    result.append(('|', or_result))
if xor_result > 0 and len(result) < 5:
    result.append(('^', xor_result))

print(len(result))
for op, const in result:
    print(op, const)
